<?php
declare(strict_types=1);
require_once __DIR__.'/global_brand_v704.php';

function mp550_enabled(): bool {return function_exists('setting_bool')?setting_bool('marketplace_v550_enabled',true):true;}
function mp550_table(string $name): bool {try{$q=db()->prepare("SHOW TABLES LIKE ?");$q->execute([$name]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;}}
function mp550_tenant_id(): ?int {if(function_exists('tenant_id')){$v=(int)(tenant_id()?:0);return $v>0?$v:null;}return null;}
function mp550_city_id(): ?int {if(function_exists('tenant_city_id')){$v=(int)(tenant_city_id()?:0);return $v>0?$v:null;}if(function_exists('tenant_query_city_id')){$v=(int)tenant_query_city_id();return $v>0?$v:null;}return null;}
function mp550_slug(string $s): string {$x=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$s),'-'));return $x!==''?$x:'shop';}
function mp550_money(float $v): string {return 'Rs '.number_format($v,0);}
function mp550_json($v): string {return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}';}
function mp550_safe_url(string $v): string {$v=trim($v);if($v==='')return '';if(str_starts_with($v,'/'))return $v;return filter_var($v,FILTER_VALIDATE_URL)?$v:'';}
function mp550_order_number(string $prefix='ORD'): string {return 'SHP-'.$prefix.'-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));}
function mp550_checkout_group(): string {return 'CHK-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(4)));}

function mp551_is_lock_error(Throwable $e): bool {
    $sqlState=(string)$e->getCode();$driver=0;
    if($e instanceof PDOException&&is_array($e->errorInfo??null))$driver=(int)($e->errorInfo[1]??0);
    $msg=strtolower($e->getMessage());
    return $sqlState==='40001'||in_array($driver,[1213,1205],true)||str_contains($msg,'deadlock')||str_contains($msg,'lock wait timeout');
}
function mp551_retry_limit(): int {return max(1,min(6,(int)(function_exists('setting')?setting('marketplace_v551_deadlock_retries','4'):4)));}
function mp551_retry_delay(int $attempt): void {$base=max(20,min(500,(int)(function_exists('setting')?setting('marketplace_v551_deadlock_base_delay_ms','60'):60)));$jitter=random_int(0,max(10,$base));usleep((int)(($base*(2**max(0,$attempt-1))+$jitter)*1000));}
function mp551_transaction(callable $callback){
    if(db()->inTransaction())return $callback();
    $max=mp551_retry_limit();
    for($attempt=1;$attempt<=$max;$attempt++){
        try{db()->beginTransaction();$result=$callback();db()->commit();return $result;}
        catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if(!mp551_is_lock_error($e)||$attempt>=$max)throw $e;if(function_exists('runtime_log'))runtime_log('Marketplace v5.5.1 transaction retry '.$attempt,$e);mp551_retry_delay($attempt);}
    }
    throw new RuntimeException('Marketplace transaction could not be completed.');
}
function mp551_get_lock(string $name,int $timeout=0): bool {try{$q=db()->prepare('SELECT GET_LOCK(?,?)');$q->execute([$name,max(0,$timeout)]);return (int)$q->fetchColumn()===1;}catch(Throwable $e){return true;}}
function mp551_release_lock(string $name): void {try{$q=db()->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$name]);}catch(Throwable $e){}}
function mp551_lock_products(array $ids): array {
    $ids=array_values(array_unique(array_filter(array_map('intval',$ids),fn($v)=>$v>0)));sort($ids,SORT_NUMERIC);if(!$ids)return [];
    $marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT id,stock,status FROM store_products WHERE id IN ({$marks}) ORDER BY id FOR UPDATE");$q->execute($ids);$rows=$q->fetchAll()?:[];$out=[];foreach($rows as $r)$out[(int)$r['id']]=$r;return $out;
}

function mp550_bootstrap_legacy_shops(): void {
    static $done=false;if($done)return;$done=true;
    if(!mp550_enabled()||!mp550_table('marketplace_shops_v550')||!mp550_table('store_products')||!setting_bool('marketplace_v550_auto_shop_bootstrap',true))return;
    $lock='shahkotpk:mp550:bootstrap:'.(string)(mp550_tenant_id()??0).':'.(string)(mp550_city_id()??0);
    if(function_exists('setting_bool')&&setting_bool('marketplace_v551_bootstrap_locking',true)&&!mp551_get_lock($lock,0))return;
    try{
        $sql="SELECT p.seller_user_id,p.business_id,MAX(p.city_id) city_id,COALESCE(MAX(b.name),MAX(u.name),'Marketplace Shop') shop_name FROM store_products p LEFT JOIN businesses b ON b.id=p.business_id LEFT JOIN users u ON u.id=p.seller_user_id WHERE p.seller_user_id IS NOT NULL GROUP BY p.seller_user_id,p.business_id ORDER BY p.seller_user_id,p.business_id LIMIT 500";
        foreach(db()->query($sql)->fetchAll() as $r){
            $owner=(int)$r['seller_user_id'];$business=(int)($r['business_id']??0);$name=trim((string)$r['shop_name'])?:('Shop '.$owner);
            $q=db()->prepare('SELECT id FROM marketplace_shops_v550 WHERE owner_user_id=? AND ((business_id IS NULL AND ?=0) OR business_id=?) ORDER BY id LIMIT 1');$q->execute([$owner,$business,$business]);$shopId=(int)$q->fetchColumn();
            if(!$shopId){
                $slug=mp550_slug($name).'-'.$owner.($business?'-'.$business:'');
                db()->prepare("INSERT IGNORE INTO marketplace_shops_v550(tenant_id,city_id,business_id,owner_user_id,name,slug,status,verified,created_at,updated_at) VALUES(?,?,?,?,?,?,'active',0,NOW(),NOW())")->execute([mp550_tenant_id(),(int)($r['city_id']??0)?:mp550_city_id(),$business?:null,$owner,$name,$slug]);
                $q=db()->prepare('SELECT id FROM marketplace_shops_v550 WHERE owner_user_id=? AND ((business_id IS NULL AND ?=0) OR business_id=?) ORDER BY id LIMIT 1');$q->execute([$owner,$business,$business]);$shopId=(int)$q->fetchColumn();
                if(!$shopId){$q=db()->prepare('SELECT id FROM marketplace_shops_v550 WHERE slug=? LIMIT 1');$q->execute([$slug]);$shopId=(int)$q->fetchColumn();}
            }
            if($shopId)db()->prepare('INSERT IGNORE INTO marketplace_product_meta_v550(product_id,shop_id,created_at,updated_at) SELECT p.id,?,NOW(),NOW() FROM store_products p WHERE p.seller_user_id=? AND ((p.business_id IS NULL AND ?=0) OR p.business_id=?) ORDER BY p.id')->execute([$shopId,$owner,$business,$business]);
        }
    }catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Marketplace v5.5.1 legacy shop bootstrap skipped',$e);}finally{mp551_release_lock($lock);}
}

function mp550_shops(array $filters=[],int $limit=100): array {
    mp550_bootstrap_legacy_shops();$where=["s.status='active'"];$p=[];
    if(($tid=mp550_tenant_id())!==null){$where[]='(s.tenant_id IS NULL OR s.tenant_id=?)';$p[]=$tid;}
    if(($cid=mp550_city_id())!==null){$where[]='(s.city_id IS NULL OR s.city_id=?)';$p[]=$cid;}
    if(!empty($filters['owner'])){$where[]='s.owner_user_id=?';$p[]=(int)$filters['owner'];}
    if(!empty($filters['q'])){$where[]='(s.name LIKE ? OR s.description LIKE ? OR s.address LIKE ?)';$like='%'.$filters['q'].'%';array_push($p,$like,$like,$like);}
    $sql='SELECT s.*,u.name owner_name,b.name business_name,(SELECT COUNT(*) FROM marketplace_product_meta_v550 m JOIN store_products p2 ON p2.id=m.product_id WHERE m.shop_id=s.id AND p2.status=\'published\') product_count FROM marketplace_shops_v550 s JOIN users u ON u.id=s.owner_user_id LEFT JOIN businesses b ON b.id=s.business_id WHERE '.implode(' AND ',$where).' ORDER BY s.featured DESC,s.verified DESC,s.name LIMIT '.max(1,min(500,$limit));
    try{$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}
}
function mp550_shop(int $id): ?array {try{$q=db()->prepare('SELECT s.*,u.name owner_name,b.name business_name FROM marketplace_shops_v550 s JOIN users u ON u.id=s.owner_user_id LEFT JOIN businesses b ON b.id=s.business_id WHERE s.id=? LIMIT 1');$q->execute([$id]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function mp550_user_shops(int $uid,bool $posOnly=false): array {mp550_bootstrap_legacy_shops();try{$sql="SELECT DISTINCT s.*,CASE WHEN s.owner_user_id=? THEN 'owner' ELSE COALESCE(m.role,'staff') END access_role FROM marketplace_shops_v550 s LEFT JOIN marketplace_shop_members_v550 m ON m.shop_id=s.id AND m.user_id=? LEFT JOIN marketplace_pos_assignments_v550 pa ON pa.shop_id=s.id AND pa.user_id=? AND pa.status=1 WHERE s.status='active' AND (s.owner_user_id=? OR (m.user_id=? AND m.status=1)".($posOnly?' OR pa.user_id=?':'').') ORDER BY s.name';$params=[$uid,$uid,$uid,$uid,$uid];if($posOnly)$params[]=$uid;$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}

function mp550_categories(): array {try{return db()->query('SELECT * FROM store_categories WHERE status=1 ORDER BY sort_order,name')->fetchAll()?:[];}catch(Throwable $e){return [];}}
function mp550_product(int|string $id): ?array {
    $field=(is_int($id)||ctype_digit((string)$id))?'p.id':'p.slug';$sql="SELECT p.*,sc.name category_name,sc.slug category_slug,u.name seller_name,c.name city_name,m.shop_id,m.sku,m.barcode,m.brand,m.compare_at_price,m.cost_price,m.low_stock_threshold,m.min_order_qty,m.max_order_qty,m.warranty_text,m.return_days,m.gallery_json,m.tags_json,s.name shop_name,s.slug shop_slug,s.logo_url shop_logo,s.verified shop_verified FROM store_products p JOIN store_categories sc ON sc.id=p.category_id JOIN users u ON u.id=p.seller_user_id LEFT JOIN cities c ON c.id=p.city_id LEFT JOIN marketplace_product_meta_v550 m ON m.product_id=p.id LEFT JOIN marketplace_shops_v550 s ON s.id=m.shop_id WHERE {$field}=? LIMIT 1";
    try{$q=db()->prepare($sql);$q->execute([$id]);$r=$q->fetch();if(!$r)return null;$d=mp550_best_discount($r,1,null);$r['sale_price']=$d['final'];$r['discount_info']=$d;return $r;}catch(Throwable $e){return null;}
}
function mp550_products(array $filters=[],int $limit=40): array {
    mp550_bootstrap_legacy_shops();$where=["p.status='published'"];$p=[];
    if(($cid=mp550_city_id())!==null){$where[]='(p.city_id IS NULL OR p.city_id=?)';$p[]=$cid;}
    if(!empty($filters['shop'])){$where[]='m.shop_id=?';$p[]=(int)$filters['shop'];}
    if(!empty($filters['seller'])){$where[]='p.seller_user_id=?';$p[]=(int)$filters['seller'];}
    if(!empty($filters['category'])){$where[]='sc.slug=?';$p[]=$filters['category'];}
    if(!empty($filters['type'])){$where[]='p.product_type=?';$p[]=$filters['type'];}
    if(isset($filters['sale_mode'])&&$filters['sale_mode']!==''){$where[]='p.sale_mode=?';$p[]=$filters['sale_mode'];}
    if(!empty($filters['q'])){$where[]='(p.title LIKE ? OR p.short_description LIKE ? OR p.description LIKE ? OR m.brand LIKE ? OR m.sku LIKE ?)';$like='%'.$filters['q'].'%';array_push($p,$like,$like,$like,$like,$like);}
    if(!empty($filters['featured']))$where[]='p.featured=1';
    $order='p.featured DESC,p.id DESC';if(($filters['sort']??'')==='price_asc')$order='p.price ASC';elseif(($filters['sort']??'')==='price_desc')$order='p.price DESC';elseif(($filters['sort']??'')==='stock')$order='p.stock DESC';
    $sql="SELECT p.*,sc.name category_name,sc.slug category_slug,u.name seller_name,c.name city_name,m.shop_id,m.sku,m.brand,m.compare_at_price,s.name shop_name,s.slug shop_slug,s.logo_url shop_logo,s.verified shop_verified FROM store_products p JOIN store_categories sc ON sc.id=p.category_id JOIN users u ON u.id=p.seller_user_id LEFT JOIN cities c ON c.id=p.city_id LEFT JOIN marketplace_product_meta_v550 m ON m.product_id=p.id LEFT JOIN marketplace_shops_v550 s ON s.id=m.shop_id WHERE ".implode(' AND ',$where)." ORDER BY {$order} LIMIT ".max(1,min(200,$limit));
    try{$q=db()->prepare($sql);$q->execute($p);$rows=$q->fetchAll()?:[];foreach($rows as &$r){$d=mp550_best_discount($r,1,null);$r['sale_price']=$d['final'];$r['discount_info']=$d;}return $rows;}catch(Throwable $e){return [];}
}

function mp550_discount_rows(bool $activeOnly=true): array {if(!mp550_table('marketplace_discounts_v550'))return [];try{$where=$activeOnly?"WHERE status=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) AND (usage_limit IS NULL OR usage_count<usage_limit)":'';$q=db()->query("SELECT * FROM marketplace_discounts_v550 {$where} ORDER BY automatic_apply DESC,id DESC");return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function mp550_best_discount(array $product,int $qty=1,?string $coupon=null): array {
    $base=(float)$product['price'];$best=['id'=>null,'name'=>'','code'=>'','amount'=>0.0,'final'=>$base,'percent'=>0.0];if($base<=0)return $best;
    foreach(mp550_discount_rows(true) as $d){
        if($coupon!==null&&$coupon!==''&&strcasecmp((string)$d['code'],$coupon)!==0)continue;
        if(($coupon===null||$coupon==='')&&!$d['automatic_apply'])continue;
        if(!empty($d['shop_id'])&&(int)$d['shop_id']!==(int)($product['shop_id']??0))continue;
        if(!empty($d['product_id'])&&(int)$d['product_id']!==(int)$product['id'])continue;
        if(!empty($d['category_id'])&&(int)$d['category_id']!==(int)$product['category_id'])continue;
        $line=$base*$qty;if($line<(float)$d['min_order_amount'])continue;$amt=$d['discount_type']==='fixed'?(float)$d['discount_value']:$line*((float)$d['discount_value']/100);if($d['max_discount_amount']!==null)$amt=min($amt,(float)$d['max_discount_amount']);$amt=max(0,min($line,$amt));if($amt>$best['amount'])$best=['id'=>(int)$d['id'],'name'=>(string)$d['name'],'code'=>(string)($d['code']??''),'amount'=>$amt,'final'=>max(0,$line-$amt)/$qty,'percent'=>$line>0?($amt/$line*100):0];
    }
    return $best;
}
function mp550_validate_coupon(string $code): ?array {$code=strtoupper(trim($code));if($code==='')return null;try{$q=db()->prepare("SELECT * FROM marketplace_discounts_v550 WHERE UPPER(code)=? AND status=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) AND (usage_limit IS NULL OR usage_count<usage_limit) LIMIT 1");$q->execute([$code]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}

function mp550_cart(): array {return is_array($_SESSION['mp550_cart']??null)?$_SESSION['mp550_cart']:[];}
function mp550_cart_add(int $productId,int $qty=1): void {$p=mp550_product($productId);if(!$p||$p['status']!=='published'||$p['sale_mode']!=='fixed')throw new RuntimeException('This product is not available for direct purchase.');if((int)$p['stock']<1)throw new RuntimeException('Product is out of stock.');$max=(int)($p['max_order_qty']??0);$min=max(1,(int)($p['min_order_qty']??1));$qty=max($min,$qty);if($max>0)$qty=min($qty,$max);$qty=min($qty,(int)$p['stock']);$cart=mp550_cart();$old=(int)($cart[$productId]??0);$cart[$productId]=min((int)$p['stock'],$old+$qty);$_SESSION['mp550_cart']=$cart;}
function mp550_cart_set(int $productId,int $qty): void {$cart=mp550_cart();if($qty<=0){unset($cart[$productId]);$_SESSION['mp550_cart']=$cart;return;}$p=mp550_product($productId);if(!$p)return;$max=(int)($p['max_order_qty']??0);if($max>0)$qty=min($qty,$max);$cart[$productId]=max(1,min($qty,(int)$p['stock']));$_SESSION['mp550_cart']=$cart;}
function mp550_cart_clear(): void {unset($_SESSION['mp550_cart'],$_SESSION['mp550_coupon']);}
function mp550_cart_count(): int {return array_sum(array_map('intval',mp550_cart()));}
function mp550_cart_details(): array {
    $rows=[];$subtotal=0;$discount=0;$shipping=0;$coupon=(string)($_SESSION['mp550_coupon']??'');$couponRow=$coupon!==''?mp550_validate_coupon($coupon):null;
    foreach(mp550_cart() as $pid=>$qty){$p=mp550_product((int)$pid);if(!$p||$p['status']!=='published'||$p['sale_mode']!=='fixed'||(int)$p['stock']<1)continue;$qty=max(1,min((int)$qty,(int)$p['stock']));$auto=mp550_best_discount($p,$qty,null);$cp=$couponRow?mp550_best_discount($p,$qty,$coupon):['amount'=>0,'final'=>(float)$p['price'],'id'=>null,'name'=>'','code'=>'','percent'=>0];$d=$cp['amount']>$auto['amount']?$cp:$auto;$line=(float)$p['price']*$qty;$disc=(float)$d['amount'];$ship=$p['product_type']==='digital'?0:(float)$p['shipping_charge'];$subtotal+=$line;$discount+=$disc;$shipping+=$ship;$rows[]=['product'=>$p,'qty'=>$qty,'line_subtotal'=>$line,'discount'=>$disc,'line_total'=>$line-$disc,'shipping'=>$ship,'discount_info'=>$d];}
    return ['items'=>$rows,'subtotal'=>$subtotal,'discount'=>$discount,'shipping'=>$shipping,'grand_total'=>max(0,$subtotal-$discount+$shipping),'coupon'=>$coupon];
}
function mp550_apply_coupon(string $code): bool {$r=mp550_validate_coupon($code);if(!$r)return false;$_SESSION['mp550_coupon']=strtoupper(trim($code));return true;}

function mp550_commission_for_item(array $p,float $net): array {
    if(!setting_bool('marketplace_v550_commission_enabled',true))return ['percent'=>0.0,'flat'=>0.0,'amount'=>0.0,'rule'=>'Disabled'];
    $default=(float)setting('marketplace_v550_default_commission_percent','8');$percent=$default;$flat=0.0;$name='Platform default';$shopId=(int)($p['shop_id']??0);
    if($shopId){$shop=mp550_shop($shopId);if($shop&&$shop['commission_mode']==='disabled')return ['percent'=>0,'flat'=>0,'amount'=>0,'rule'=>'Shop commission disabled'];if($shop&&$shop['commission_mode']==='override'&&$shop['commission_percent']!==null){$percent=(float)$shop['commission_percent'];$name='Shop override';}}
    try{$sql="SELECT * FROM marketplace_commission_rules_v550 WHERE status=1 AND (tenant_id IS NULL OR tenant_id=?) AND (shop_id IS NULL OR shop_id=?) AND (seller_user_id IS NULL OR seller_user_id=?) AND (category_id IS NULL OR category_id=?) AND (product_id IS NULL OR product_id=?) ORDER BY (product_id IS NOT NULL) DESC,(seller_user_id IS NOT NULL) DESC,(shop_id IS NOT NULL) DESC,(category_id IS NOT NULL) DESC,priority ASC,id ASC LIMIT 1";$q=db()->prepare($sql);$q->execute([mp550_tenant_id(),$shopId?:null,(int)$p['seller_user_id'],(int)$p['category_id'],(int)$p['id']]);if($r=$q->fetch()){$percent=(float)$r['percent_rate'];$flat=(float)$r['flat_fee'];$name=(string)$r['name'];}}catch(Throwable $e){}
    $amount=max(0,min($net,$net*($percent/100)+$flat));return ['percent'=>$percent,'flat'=>$flat,'amount'=>$amount,'rule'=>$name];
}

function mp550_affiliate_profile(int $uid,bool $create=true): ?array {
    if(!setting_bool('marketplace_v550_affiliate_enabled',true)||!mp550_table('marketplace_affiliates_v550'))return null;
    try{$q=db()->prepare('SELECT a.*,u.name,u.email FROM marketplace_affiliates_v550 a JOIN users u ON u.id=a.user_id WHERE a.user_id=? LIMIT 1');$q->execute([$uid]);$r=$q->fetch();if($r||!$create)return $r?:null;$code='A'.$uid.'-'.strtoupper(substr(hash('sha256',$uid.'|'.csrf_token()),0,7));db()->prepare("INSERT IGNORE INTO marketplace_affiliates_v550(tenant_id,user_id,code,status,approved_at,created_at,updated_at) VALUES(?,?,?,'active',NOW(),NOW(),NOW())")->execute([mp550_tenant_id(),$uid,$code]);return mp550_affiliate_profile($uid,false);}catch(Throwable $e){return null;}
}
function mp550_capture_referral(?int $productId=null): void {
    if(!setting_bool('marketplace_v550_affiliate_enabled',true))return;$code=trim((string)($_GET['ref']??''));if($code==='')return;
    try{$q=db()->prepare("SELECT * FROM marketplace_affiliates_v550 WHERE code=? AND status='active' LIMIT 1");$q->execute([$code]);$a=$q->fetch();if(!$a)return;$me=current_user();if($me&&(int)$me['id']===(int)$a['user_id'])return;$_SESSION['mp550_affiliate_code']=$code;$days=max(1,min(365,(int)setting('marketplace_v550_affiliate_cookie_days','30')));setcookie('mp550_ref',$code,['expires'=>time()+86400*$days,'path'=>'/','samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true]);$session=hash('sha256',session_id().'|'.$code.'|'.($productId?:0));db()->prepare('INSERT IGNORE INTO marketplace_affiliate_clicks_v550(affiliate_id,product_id,session_key,referrer,created_at) VALUES(?,?,?,?,NOW())')->execute([(int)$a['id'],$productId?:null,$session,mb_substr((string)($_SERVER['HTTP_REFERER']??''),0,500)]);}catch(Throwable $e){}
}
function mp550_current_affiliate(?int $buyerId=null): ?array {$code=(string)($_SESSION['mp550_affiliate_code']??($_COOKIE['mp550_ref']??''));if($code==='')return null;try{$q=db()->prepare("SELECT * FROM marketplace_affiliates_v550 WHERE code=? AND status='active' LIMIT 1");$q->execute([$code]);$a=$q->fetch();if(!$a||($buyerId&&$buyerId===(int)$a['user_id']))return null;return $a;}catch(Throwable $e){return null;}}
function mp550_affiliate_stats(int $uid): array {$a=mp550_affiliate_profile($uid,true);if(!$a)return ['clicks'=>0,'orders'=>0,'pending'=>0,'approved'=>0,'paid'=>0,'available'=>0];try{$q=db()->prepare("SELECT (SELECT COUNT(*) FROM marketplace_affiliate_clicks_v550 WHERE affiliate_id=?) clicks,(SELECT COUNT(*) FROM marketplace_affiliate_conversions_v550 WHERE affiliate_id=?) orders,(SELECT COALESCE(SUM(commission_amount),0) FROM marketplace_affiliate_conversions_v550 WHERE affiliate_id=? AND status='pending') pending,(SELECT COALESCE(SUM(commission_amount),0) FROM marketplace_affiliate_conversions_v550 WHERE affiliate_id=? AND status='approved') approved,(SELECT COALESCE(SUM(commission_amount),0) FROM marketplace_affiliate_conversions_v550 WHERE affiliate_id=? AND status='paid') paid");$q->execute(array_fill(0,5,(int)$a['id']));$r=$q->fetch()?:[];$paidReq=0.0;$p=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM marketplace_payouts_v550 WHERE payee_type='affiliate' AND payee_user_id=? AND status IN ('requested','approved','paid')");$p->execute([$uid]);$paidReq=(float)$p->fetchColumn();$p=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM marketplace_payouts_v550 WHERE payee_type='affiliate' AND payee_user_id=? AND status='paid'");$p->execute([$uid]);$r['paid']=(float)$p->fetchColumn();$r['available']=max(0,(float)($r['approved']??0)-$paidReq);return $r;}catch(Throwable $e){return ['clicks'=>0,'orders'=>0,'pending'=>0,'approved'=>0,'paid'=>0,'available'=>0];}}

function mp550_checkout(int $buyerId,array $customer,string $paymentMethod='cod',string $source='web'): array {
    if(!mp550_enabled())throw new RuntimeException('Marketplace is disabled.');$cart=mp550_cart_details();if(!$cart['items'])throw new RuntimeException('Your cart is empty.');
    $allowed=['cod','advance','bank_transfer','cash','card'];if(!in_array($paymentMethod,$allowed,true))throw new RuntimeException('Invalid payment method.');if($paymentMethod==='cod'&&!setting_bool('marketplace_v550_allow_cod',true))throw new RuntimeException('Cash on delivery is disabled.');if($paymentMethod==='advance'&&!setting_bool('marketplace_v550_allow_advance',true))throw new RuntimeException('Advance payment is disabled.');if($paymentMethod==='bank_transfer'&&!setting_bool('marketplace_v550_allow_bank_transfer',true))throw new RuntimeException('Bank transfer is disabled.');
    $groups=[];$productIds=[];foreach($cart['items'] as $it){$p=$it['product'];$key=(int)$p['seller_user_id'].'|'.(int)($p['shop_id']??0);$groups[$key][]=$it;$productIds[]=(int)$p['id'];}ksort($groups,SORT_STRING);$group=mp550_checkout_group();$affiliate=$source==='pos'?null:mp550_current_affiliate($buyerId);
    $result=mp551_transaction(function()use($buyerId,$customer,$paymentMethod,$source,$cart,$groups,$group,$affiliate,$productIds){
        $locked=mp551_lock_products($productIds);foreach($cart['items'] as $it){$pid=(int)$it['product']['id'];$qty=(int)$it['qty'];if(!isset($locked[$pid])||(int)$locked[$pid]['stock']<$qty)throw new RuntimeException('Stock changed for '.$it['product']['title'].'. Refresh cart and try again.');}
        $orderIds=[];$paymentQueue=[];
        foreach($groups as $items){$first=$items[0]['product'];$seller=(int)$first['seller_user_id'];$shopId=(int)($first['shop_id']??0)?:null;$sub=0;$disc=0;$ship=0;$platform=0;$affAmount=0;$lineCalcs=[];
            usort($items,fn($a,$b)=>(int)$a['product']['id']<=>(int)$b['product']['id']);
            foreach($items as $it){$p=$it['product'];$sub+=(float)$it['line_subtotal'];$disc+=(float)$it['discount'];$ship+=(float)$it['shipping'];$net=(float)$it['line_total'];$com=mp550_commission_for_item($p,$net);$platform+=(float)$com['amount'];$aff=0.0;if($affiliate){$rate=$affiliate['commission_rate']!==null?(float)$affiliate['commission_rate']:(float)setting('marketplace_v550_default_affiliate_percent','3');$aff=max(0,$net*($rate/100));$affAmount+=$aff;}$lineCalcs[]=['it'=>$it,'com'=>$com,'affiliate'=>$aff];}
            $grand=max(0,$sub-$disc+$ship);$sellerNet=max(0,$grand-$platform-$affAmount);$number=mp550_order_number($source==='pos'?'POS':'ORD');$status=$source==='pos'?'completed':'pending';$paymentStatus=in_array($paymentMethod,['cash','card'],true)?'paid':'unpaid';
            $q=db()->prepare('INSERT INTO marketplace_orders_v550(order_number,checkout_group,tenant_id,city_id,shop_id,seller_user_id,buyer_user_id,source,customer_name,customer_phone,customer_email,shipping_address,customer_note,subtotal,discount_total,shipping_total,grand_total,platform_commission,affiliate_commission,seller_net,affiliate_user_id,affiliate_code,coupon_code,payment_method,payment_status,fulfillment_status,status,placed_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');
            $q->execute([$number,$group,mp550_tenant_id(),mp550_city_id(),$shopId,$seller,$buyerId?:null,$source,mb_substr(trim((string)($customer['name']??'Customer')),0,190),mb_substr(trim((string)($customer['phone']??'')),0,60),mb_substr(trim((string)($customer['email']??'')),0,190),trim((string)($customer['address']??'')),trim((string)($customer['note']??'')),$sub,$disc,$ship,$grand,$platform,$affAmount,$sellerNet,$affiliate?(int)$affiliate['user_id']:null,$affiliate?(string)$affiliate['code']:null,(string)($cart['coupon']??''),$paymentMethod,$paymentStatus,$source==='pos'?'fulfilled':'unfulfilled',$status]);$orderId=(int)db()->lastInsertId();$orderIds[]=$orderId;
            $iq=db()->prepare('INSERT INTO marketplace_order_items_v550(order_id,product_id,shop_id,seller_user_id,title,sku,image_url,quantity,unit_price,discount_amount,line_total,platform_commission,affiliate_commission,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');
            foreach($lineCalcs as $lc){$it=$lc['it'];$p=$it['product'];$qty=(int)$it['qty'];$iq->execute([$orderId,(int)$p['id'],$shopId,$seller,(string)$p['title'],(string)($p['sku']??''),(string)($p['image_url']??''),$qty,(float)$p['price'],(float)$it['discount'],(float)$it['line_total'],(float)$lc['com']['amount'],(float)$lc['affiliate']]);$u=db()->prepare("UPDATE store_products SET stock=GREATEST(0,stock-?),status=IF(stock-?<=0,'soldout',status) WHERE id=? AND stock>=?");$u->execute([$qty,$qty,(int)$p['id'],$qty]);if($u->rowCount()<1)throw new RuntimeException('Stock changed for '.$p['title'].'. Refresh cart and try again.');}
            db()->prepare('INSERT INTO marketplace_order_status_log_v550(order_id,user_id,old_status,new_status,note,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$orderId,$buyerId?:null,null,$status,$source==='pos'?'POS sale completed':'Order placed']);
            if($affiliate&&$affAmount>0){$rate=$affiliate['commission_rate']!==null?(float)$affiliate['commission_rate']:(float)setting('marketplace_v550_default_affiliate_percent','3');db()->prepare("INSERT INTO marketplace_affiliate_conversions_v550(affiliate_id,affiliate_user_id,order_id,order_amount,commission_rate,commission_amount,status,created_at) VALUES(?,?,?,?,?,?,'pending',NOW())")->execute([(int)$affiliate['id'],(int)$affiliate['user_id'],$orderId,$grand,$rate,$affAmount]);}
            if($paymentMethod==='advance')$paymentQueue[]=['order_id'=>$orderId,'amount'=>$grand];
        }
        if(!empty($cart['coupon']))db()->prepare('UPDATE marketplace_discounts_v550 SET usage_count=usage_count+1 WHERE UPPER(code)=?')->execute([strtoupper((string)$cart['coupon'])]);
        return ['group'=>$group,'orders'=>$orderIds,'payments'=>$paymentQueue];
    });
    if($paymentMethod==='advance'&&function_exists('create_payment_order'))foreach($result['payments'] as $pay){try{$pid=create_payment_order($buyerId,(float)$pay['amount'],'ecommerce',null,null,null,'none',['marketplace_v550_order_id'=>(int)$pay['order_id']]);db()->prepare('UPDATE marketplace_orders_v550 SET payment_order_id=? WHERE id=? AND payment_order_id IS NULL')->execute([$pid,(int)$pay['order_id']]);}catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Marketplace payment order creation deferred',$e);}}
    if($source==='web')mp550_cart_clear();unset($result['payments']);return $result;
}

function mp550_order(int $id): ?array {try{$q=db()->prepare('SELECT o.*,su.name seller_name,bu.name buyer_name,s.name shop_name FROM marketplace_orders_v550 o JOIN users su ON su.id=o.seller_user_id LEFT JOIN users bu ON bu.id=o.buyer_user_id LEFT JOIN marketplace_shops_v550 s ON s.id=o.shop_id WHERE o.id=? LIMIT 1');$q->execute([$id]);$o=$q->fetch();if(!$o)return null;$q=db()->prepare('SELECT * FROM marketplace_order_items_v550 WHERE order_id=? ORDER BY id');$q->execute([$id]);$o['items']=$q->fetchAll()?:[];$q=db()->prepare('SELECT l.*,u.name user_name FROM marketplace_order_status_log_v550 l LEFT JOIN users u ON u.id=l.user_id WHERE l.order_id=? ORDER BY l.id DESC');$q->execute([$id]);$o['log']=$q->fetchAll()?:[];return $o;}catch(Throwable $e){return null;}}
function mp550_orders(array $filters=[],int $limit=100): array {$w=['1=1'];$p=[];if(!empty($filters['seller'])){$w[]='o.seller_user_id=?';$p[]=(int)$filters['seller'];}if(!empty($filters['buyer'])){$w[]='o.buyer_user_id=?';$p[]=(int)$filters['buyer'];}if(!empty($filters['shop'])){$w[]='o.shop_id=?';$p[]=(int)$filters['shop'];}if(!empty($filters['status'])){$w[]='o.status=?';$p[]=$filters['status'];}if(($tid=mp550_tenant_id())!==null){$w[]='(o.tenant_id IS NULL OR o.tenant_id=?)';$p[]=$tid;}try{$q=db()->prepare('SELECT o.*,s.name shop_name,su.name seller_name,bu.name buyer_name FROM marketplace_orders_v550 o LEFT JOIN marketplace_shops_v550 s ON s.id=o.shop_id JOIN users su ON su.id=o.seller_user_id LEFT JOIN users bu ON bu.id=o.buyer_user_id WHERE '.implode(' AND ',$w).' ORDER BY o.id DESC LIMIT '.max(1,min(500,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function mp550_update_order_status(int $orderId,string $status,int $actor,string $note=''): void {
    $allowed=['pending','confirmed','processing','ready','shipped','delivered','completed','cancelled','refunded'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid order status.');
    mp551_transaction(function()use($orderId,$status,$actor,$note){$q=db()->prepare('SELECT * FROM marketplace_orders_v550 WHERE id=? FOR UPDATE');$q->execute([$orderId]);$o=$q->fetch();if(!$o)throw new RuntimeException('Order not found.');$old=(string)$o['status'];db()->prepare('UPDATE marketplace_orders_v550 SET status=?,fulfillment_status=CASE WHEN ? IN (\'delivered\',\'completed\') THEN \'fulfilled\' WHEN ?=\'cancelled\' THEN \'cancelled\' ELSE fulfillment_status END,updated_at=NOW() WHERE id=?')->execute([$status,$status,$status,$orderId]);db()->prepare('INSERT INTO marketplace_order_status_log_v550(order_id,user_id,old_status,new_status,note,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$orderId,$actor,$old,$status,mb_substr($note,0,500)]);if(in_array($status,['delivered','completed'],true))db()->prepare("UPDATE marketplace_affiliate_conversions_v550 SET status='approved',approved_at=COALESCE(approved_at,NOW()) WHERE order_id=? AND status='pending'")->execute([$orderId]);if($status==='cancelled'&&!in_array($old,['cancelled','refunded'],true)){$q=db()->prepare('SELECT product_id,quantity FROM marketplace_order_items_v550 WHERE order_id=? ORDER BY product_id');$q->execute([$orderId]);$items=$q->fetchAll()?:[];mp551_lock_products(array_column($items,'product_id'));foreach($items as $it)db()->prepare("UPDATE store_products SET stock=stock+?,status=IF(status='soldout','published',status) WHERE id=?")->execute([(int)$it['quantity'],(int)$it['product_id']]);db()->prepare("UPDATE marketplace_affiliate_conversions_v550 SET status='cancelled' WHERE order_id=? AND status IN ('pending','approved')")->execute([$orderId]);}return null;});
}

function mp550_stats(?int $seller=null,?int $shop=null): array {$w=[];$p=[];if($seller){$w[]='seller_user_id=?';$p[]=$seller;}if($shop){$w[]='shop_id=?';$p[]=$shop;}$cond=$w?' WHERE '.implode(' AND ',$w):'';try{$q=db()->prepare("SELECT COUNT(*) orders,COALESCE(SUM(grand_total),0) gross,COALESCE(SUM(platform_commission),0) commission,COALESCE(SUM(seller_net),0) seller_net,SUM(status IN ('pending','confirmed','processing','ready')) open_orders,SUM(status IN ('delivered','completed')) completed FROM marketplace_orders_v550{$cond}");$q->execute($p);$r=$q->fetch()?:[];$r['products']=0;$r['shops']=0;try{$r['products']=(int)db()->query("SELECT COUNT(*) FROM store_products WHERE status='published'")->fetchColumn();$r['shops']=(int)db()->query("SELECT COUNT(*) FROM marketplace_shops_v550 WHERE status='active'")->fetchColumn();}catch(Throwable $e){}return $r;}catch(Throwable $e){return [];}}

function mp550_pos_assignments(): array {try{return db()->query('SELECT pa.*,s.name shop_name,u.name user_name,u.email user_email,ab.name assigned_by_name FROM marketplace_pos_assignments_v550 pa JOIN marketplace_shops_v550 s ON s.id=pa.shop_id JOIN users u ON u.id=pa.user_id LEFT JOIN users ab ON ab.id=pa.assigned_by ORDER BY pa.id DESC')->fetchAll()?:[];}catch(Throwable $e){return [];}}
function mp550_pos_assignment_for(int $uid,int $shopId): ?array {try{$q=db()->prepare('SELECT pa.*,s.name shop_name FROM marketplace_pos_assignments_v550 pa JOIN marketplace_shops_v550 s ON s.id=pa.shop_id WHERE pa.user_id=? AND pa.shop_id=? AND pa.status=1 LIMIT 1');$q->execute([$uid,$shopId]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function mp550_open_shift(array $assignment,int $uid,float $opening=0): int {try{$q=db()->prepare("SELECT id FROM marketplace_pos_shifts_v550 WHERE user_id=? AND shop_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([$uid,(int)$assignment['shop_id']]);$id=(int)$q->fetchColumn();if($id)return $id;db()->prepare('INSERT INTO marketplace_pos_shifts_v550(assignment_id,shop_id,user_id,opening_cash,status,opened_at) VALUES(?,?,?,?,\'open\',NOW())')->execute([(int)$assignment['id'],(int)$assignment['shop_id'],$uid,$opening]);return (int)db()->lastInsertId();}catch(Throwable $e){throw new RuntimeException('Unable to open POS shift.');}}

function mp550_auction_sync(): void {
    static $done=false;if($done||!mp550_table('marketplace_auctions_v550'))return;$done=true;
    try{$batch=max(5,min(100,(int)setting('marketplace_v551_auction_sync_batch','25')));$q=db()->prepare("SELECT id,status FROM marketplace_auctions_v550 WHERE (status='scheduled' AND starts_at<=NOW()) OR (status IN ('scheduled','live') AND ends_at<=NOW()) ORDER BY id LIMIT {$batch}");$q->execute();foreach($q->fetchAll()?:[] as $r){$id=(int)$r['id'];if($r['status']==='scheduled')db()->prepare("UPDATE marketplace_auctions_v550 SET status='live',updated_at=NOW() WHERE id=? AND status='scheduled' AND starts_at<=NOW() AND ends_at>NOW()")->execute([$id]);$e=db()->prepare("SELECT ends_at,status FROM marketplace_auctions_v550 WHERE id=? LIMIT 1");$e->execute([$id]);$row=$e->fetch();if($row&&in_array($row['status'],['scheduled','live'],true)&&strtotime((string)$row['ends_at'])<=time())mp550_finish_auction($id);}}catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Marketplace auction sync skipped',$e);}
}
function mp550_auctions(array $filters=[],int $limit=50): array {mp550_auction_sync();$w=['1=1'];$p=[];if(!empty($filters['status'])){$w[]='a.status=?';$p[]=$filters['status'];}else $w[]="a.status IN ('scheduled','live','ended','sold','no_sale')";if(!empty($filters['shop'])){$w[]='a.shop_id=?';$p[]=(int)$filters['shop'];}if(($cid=mp550_city_id())!==null){$w[]='(a.city_id IS NULL OR a.city_id=?)';$p[]=$cid;}try{$q=db()->prepare('SELECT a.*,p.slug,p.image_url,p.short_description,p.product_type,s.name shop_name,u.name seller_name,(SELECT COUNT(*) FROM marketplace_auction_bids_v550 b WHERE b.auction_id=a.id AND b.status=\'active\') bidder_count,(SELECT COUNT(*) FROM marketplace_auction_watchers_v550 w WHERE w.auction_id=a.id) watcher_count FROM marketplace_auctions_v550 a JOIN store_products p ON p.id=a.product_id LEFT JOIN marketplace_shops_v550 s ON s.id=a.shop_id JOIN users u ON u.id=a.seller_user_id WHERE '.implode(' AND ',$w).' ORDER BY FIELD(a.status,\'live\',\'scheduled\',\'ended\',\'sold\',\'no_sale\'),a.ends_at ASC LIMIT '.max(1,min(200,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function mp550_auction(int $id): ?array {mp550_auction_sync();try{$q=db()->prepare('SELECT a.*,p.slug,p.image_url,p.description,p.short_description,p.product_type,p.shipping_charge,s.name shop_name,u.name seller_name FROM marketplace_auctions_v550 a JOIN store_products p ON p.id=a.product_id LEFT JOIN marketplace_shops_v550 s ON s.id=a.shop_id JOIN users u ON u.id=a.seller_user_id WHERE a.id=? LIMIT 1');$q->execute([$id]);$a=$q->fetch();if(!$a)return null;$q=db()->prepare('SELECT e.*,u.name user_name FROM marketplace_auction_events_v550 e LEFT JOIN users u ON u.id=e.user_id WHERE e.auction_id=? ORDER BY e.id DESC LIMIT 30');$q->execute([$id]);$a['events']=$q->fetchAll()?:[];return $a;}catch(Throwable $e){return null;}}
function mp550_place_bid(int $auctionId,int $uid,float $maxBid): array {
    if(!setting_bool('marketplace_v550_auction_enabled',true))throw new RuntimeException('Auctions are disabled.');
    return mp551_transaction(function()use($auctionId,$uid,$maxBid){$q=db()->prepare('SELECT * FROM marketplace_auctions_v550 WHERE id=? FOR UPDATE');$q->execute([$auctionId]);$a=$q->fetch();if(!$a)throw new RuntimeException('Auction not found.');$now=time();if($a['status']==='scheduled'&&strtotime($a['starts_at'])<=$now){db()->prepare("UPDATE marketplace_auctions_v550 SET status='live' WHERE id=?")->execute([$auctionId]);$a['status']='live';}if($a['status']!=='live'||strtotime($a['starts_at'])>$now||strtotime($a['ends_at'])<=$now)throw new RuntimeException('Auction is not live.');if((int)$a['seller_user_id']===$uid)throw new RuntimeException('Seller cannot bid on own auction.');$minimum=max((float)$a['start_price'],(float)$a['current_price']+(float)$a['min_increment']);if($maxBid<$minimum)throw new RuntimeException('Minimum bid is '.mp550_money($minimum).'.');$q=db()->prepare('SELECT max_auto_bid FROM marketplace_auction_bids_v550 WHERE auction_id=? AND user_id=? LIMIT 1');$q->execute([$auctionId,$uid]);$old=(float)($q->fetchColumn()?:0);if($old>=$maxBid)throw new RuntimeException('Your existing automatic maximum is already equal or higher.');db()->prepare("INSERT INTO marketplace_auction_bids_v550(auction_id,user_id,max_auto_bid,effective_bid,status,created_at,updated_at) VALUES(?,?,?,0,'active',NOW(),NOW()) ON DUPLICATE KEY UPDATE max_auto_bid=VALUES(max_auto_bid),status='active',updated_at=NOW()")->execute([$auctionId,$uid,$maxBid]);$q=db()->prepare("SELECT user_id,max_auto_bid FROM marketplace_auction_bids_v550 WHERE auction_id=? AND status='active' ORDER BY max_auto_bid DESC,updated_at ASC,id ASC LIMIT 2");$q->execute([$auctionId]);$top=$q->fetchAll();$leader=$top[0]??null;$second=$top[1]??null;if(!$leader)throw new RuntimeException('Bid could not be recorded.');$current=(float)$a['start_price'];if($second)$current=min((float)$leader['max_auto_bid'],max($current,(float)$second['max_auto_bid']+(float)$a['min_increment']));else $current=max($current,min((float)$leader['max_auto_bid'],$minimum));$current=max((float)$a['current_price'],$current);$end=strtotime($a['ends_at']);$remaining=$end-time();$extensions=(int)$a['extension_count'];if($remaining<=(int)$a['anti_snipe_seconds']&&$extensions<(int)$a['max_extensions']){$end=time()+(int)$a['anti_snipe_seconds'];$extensions++;}db()->prepare('UPDATE marketplace_auction_bids_v550 SET effective_bid=CASE WHEN user_id=? THEN ? ELSE effective_bid END WHERE auction_id=?')->execute([(int)$leader['user_id'],$current,$auctionId]);db()->prepare('UPDATE marketplace_auctions_v550 SET current_price=?,ends_at=?,extension_count=?,updated_at=NOW() WHERE id=?')->execute([$current,date('Y-m-d H:i:s',$end),$extensions,$auctionId]);db()->prepare("INSERT INTO marketplace_auction_events_v550(auction_id,user_id,event_type,amount,created_at) VALUES(?,?,'bid',?,NOW())")->execute([$auctionId,$uid,$current]);return ['current_price'=>$current,'leader_user_id'=>(int)$leader['user_id'],'ends_at'=>date('Y-m-d H:i:s',$end),'extended'=>$extensions>(int)$a['extension_count']];});
}
function mp550_finish_auction(int $auctionId): void {
    try{mp551_transaction(function()use($auctionId){$q=db()->prepare('SELECT * FROM marketplace_auctions_v550 WHERE id=? FOR UPDATE');$q->execute([$auctionId]);$a=$q->fetch();if(!$a||in_array($a['status'],['ended','sold','no_sale'],true))return null;if(strtotime((string)$a['ends_at'])>time())return null;$q=db()->prepare("SELECT user_id,max_auto_bid,effective_bid FROM marketplace_auction_bids_v550 WHERE auction_id=? AND status='active' ORDER BY max_auto_bid DESC,updated_at ASC,id ASC LIMIT 1");$q->execute([$auctionId]);$b=$q->fetch();$won=$b&&($a['reserve_price']===null||(float)$a['current_price']>=(float)$a['reserve_price']);$status=$won?'ended':'no_sale';db()->prepare('UPDATE marketplace_auctions_v550 SET status=?,winner_user_id=?,winning_bid=?,updated_at=NOW() WHERE id=?')->execute([$status,$won?(int)$b['user_id']:null,$won?(float)$a['current_price']:null,$auctionId]);db()->prepare('INSERT INTO marketplace_auction_events_v550(auction_id,user_id,event_type,amount,created_at) VALUES(?,?,?,?,NOW())')->execute([$auctionId,$won?(int)$b['user_id']:null,$won?'won':'no_sale',$won?(float)$a['current_price']:null]);return null;});}catch(Throwable $e){if(function_exists('runtime_log'))runtime_log('Marketplace auction finish deferred',$e);}
}
function mp550_checkout_auction(int $auctionId,int $buyerId,array $customer,string $payment='cod'): int {
    return (int)mp551_transaction(function()use($auctionId,$buyerId,$customer,$payment){$q=db()->prepare('SELECT a.*,p.shipping_charge,p.category_id FROM marketplace_auctions_v550 a JOIN store_products p ON p.id=a.product_id WHERE a.id=? FOR UPDATE');$q->execute([$auctionId]);$a=$q->fetch();if(!$a||$a['status']!=='ended'||(int)$a['winner_user_id']!==$buyerId)throw new RuntimeException('This auction is not ready for your checkout.');$tag='auction#'.$auctionId;$q=db()->prepare("SELECT id FROM marketplace_orders_v550 WHERE source='auction' AND customer_note=? LIMIT 1 FOR UPDATE");$q->execute([$tag]);if($q->fetchColumn())throw new RuntimeException('Winning auction order already exists.');$locked=mp551_lock_products([(int)$a['product_id']]);if(!isset($locked[(int)$a['product_id']])||(int)$locked[(int)$a['product_id']]['stock']<1)throw new RuntimeException('Auction product is no longer in stock.');$grand=(float)$a['winning_bid']+(float)$a['shipping_charge'];$com=mp550_commission_for_item(['id'=>(int)$a['product_id'],'shop_id'=>(int)$a['shop_id'],'seller_user_id'=>(int)$a['seller_user_id'],'category_id'=>(int)$a['category_id']],(float)$a['winning_bid']);$number=mp550_order_number('AUC');db()->prepare('INSERT INTO marketplace_orders_v550(order_number,tenant_id,city_id,shop_id,seller_user_id,buyer_user_id,source,customer_name,customer_phone,customer_email,shipping_address,customer_note,subtotal,discount_total,shipping_total,grand_total,platform_commission,affiliate_commission,seller_net,payment_method,payment_status,fulfillment_status,status,placed_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,0,?,?,?,?,0,?, ?,\'unpaid\',\'unfulfilled\',\'pending\',NOW(),NOW())')->execute([$number,mp550_tenant_id(),mp550_city_id(),(int)$a['shop_id']?:null,(int)$a['seller_user_id'],$buyerId,'auction',(string)$customer['name'],(string)($customer['phone']??''),(string)($customer['email']??''),(string)($customer['address']??''),$tag,(float)$a['winning_bid'],(float)$a['shipping_charge'],$grand,(float)$com['amount'],max(0,$grand-(float)$com['amount']),$payment]);$oid=(int)db()->lastInsertId();db()->prepare('INSERT INTO marketplace_order_items_v550(order_id,product_id,shop_id,seller_user_id,title,quantity,unit_price,discount_amount,line_total,platform_commission,affiliate_commission,created_at) VALUES(?,?,?,?,?,1,?,0,?,?,0,NOW())')->execute([$oid,(int)$a['product_id'],(int)$a['shop_id']?:null,(int)$a['seller_user_id'],(string)$a['title'],(float)$a['winning_bid'],(float)$a['winning_bid'],(float)$com['amount']]);db()->prepare("UPDATE marketplace_auctions_v550 SET status='sold',updated_at=NOW() WHERE id=? AND status='ended'")->execute([$auctionId]);db()->prepare("UPDATE store_products SET stock=GREATEST(0,stock-1),status=IF(stock-1<=0,'soldout',status) WHERE id=? AND stock>=1")->execute([(int)$a['product_id']]);return $oid;});
}

function mp550_request_payout(string $type,int $uid,float $amount,?int $shopId,string $method,string $title,string $reference): int {if(!in_array($type,['seller','affiliate'],true))throw new RuntimeException('Invalid payout type.');if($amount<=0)throw new RuntimeException('Enter a valid payout amount.');db()->prepare('INSERT INTO marketplace_payouts_v550(tenant_id,payee_type,payee_user_id,shop_id,amount,method,account_title,account_reference,status,requested_at) VALUES(?,?,?,?,?,?,?,?,\'requested\',NOW())')->execute([mp550_tenant_id(),$type,$uid,$shopId,$amount,mb_substr($method,0,40),mb_substr($title,0,190),mb_substr($reference,0,190)]);return (int)db()->lastInsertId();}

function mp550_render_home_widget(): void {$rows=mp550_products(['featured'=>1],max(4,min(12,(int)setting('marketplace_v550_home_items','8'))));if(!$rows)$rows=mp550_products([],8);echo '<section class="mp550-home"><div class="mp550-home-in"><div class="mp550-home-head"><div><span>MARKETPLACE PRO</span><h2>Shop local. Deals, trusted sellers & live auctions.</h2><p>Multi-vendor shopping with seller-routed orders, discounts, affiliate rewards and secure auction bidding.</p></div><a href="/shop.php">Explore Marketplace →</a></div><div class="mp550-home-grid">';foreach($rows as $p){$sale=(float)$p['sale_price'];$old=(float)($p['compare_at_price']?:$p['price']);echo '<a class="mp550-home-card" href="/product.php?slug='.urlencode((string)$p['slug']).'"><div class="pic"'.($p['image_url']?' style="background-image:url(\''.e($p['image_url']).'\')"':'').'><span>'.e((string)($p['shop_name']?:$p['seller_name'])).'</span></div><div><small>'.e($p['category_name']).'</small><b>'.e($p['title']).'</b><strong>'.mp550_money($sale).'</strong>'.($old>$sale?'<del>'.mp550_money($old).'</del>':'').'</div></a>';}echo '</div></div></section><link rel="stylesheet" href="/assets/marketplace-pro-5.5.0.css?v=550">';}

function mp550_public_header(string $title='Marketplace'): void {$brand=(string)(function_exists('gb704_brand_name')?gb704_brand_name('ShahkotPK'):(function_exists('tenant_brand')?tenant_brand('site_name',setting('site_name','ShahkotPK')):setting('site_name','ShahkotPK')));$city=(string)(function_exists('tenant_brand')?tenant_brand('city_name',setting('default_city','Shahkot')):setting('default_city','Shahkot'));$me=current_user();$logo=function_exists('gb704_picture')?gb704_picture('marketplace',$brand):'';$brandMarkup=$logo!==''?$logo.'<span class="gb704-module-label">Marketplace</span>':'<i>'.e(strtoupper(mb_substr($brand,0,1))).'</i><span><b>'.e($brand).'</b><small>'.e($city).' Marketplace</small></span>';echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' - '.e($brand).'</title><meta name="theme-color" content="#071325"><link rel="stylesheet" href="/assets/marketplace-pro-5.5.0.css?v=550">'.(function_exists('gb704_asset_tag')?gb704_asset_tag():'').'</head><body class="mp550-page"><header class="mp550-head"><div class="mp550-head-in"><a class="brand gb704-brand" href="/">'.$brandMarkup.'</a><nav><a href="/shop.php">Shop</a><a href="/auctions.php">Auctions</a><a href="/cart.php">Cart <em>'.mp550_cart_count().'</em></a>'.($me?'<a href="/my-orders.php">Orders</a><a href="/affiliate.php">Earn</a>':'<a href="/login.php">Login</a>').'</nav></div></header><main class="mp550-main">'; }
function mp550_public_footer(): void {echo '</main><footer class="mp550-footer"><div><b>ShahkotPK Marketplace Pro</b><span>Multi-vendor commerce · POS · Affiliate · Auctions</span><nav><a href="/shop.php">Marketplace</a><a href="/auctions.php">Auctions</a><a href="/seller-marketplace.php">Seller Center</a></nav></div></footer><script src="/assets/marketplace-pro-5.5.0.js?v=550"></script></body></html>';}
